std::string decoded_text;
std::shared_ptr<Node> current = root;
std::bitset<8> byte_buffer(0);
int bit_count = 0;
char current_byte = 0;

while (infile && bit_count < encoded_length) {
    char byte = infile.get();
    if (infile.eof() && bit_count == encoded_length - 1) break;

    byte_buffer |= static_cast<std::bitset<8>>(byte) << (8 - bit_count % 8);
    bit_count++;

    for (int i = 0; i < 8 && bit_count < encoded_length; ++i) {
        bool bit = (byte_buffer >> (7 - i)) & 1;
        if (current->left == nullptr && current->right == nullptr) {
            decoded_text += current->character;
            current = root;
        } else {
            current = bit ? current->right : current->left;
        }
        bit_count++;
    }
    byte_buffer.reset();
}

if (bit_count < encoded_length) {
    for (int i = 0; i < (encoded_length - bit_count) % 8 && bit_count < encoded_length; ++i) {
        bool bit = (byte_buffer >> (7 - i)) & 1;
        if (current->left == nullptr && current->right == nullptr) {
            decoded_text += current->character;
            current = root;
        } else {
            current = bit ? current->right : current->left;
        }
        bit_count++;
    }
}

return decoded_text;
